package za.co.loopmanager;
import android.graphics.*;import android.view.View;import java.io.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import com.google.android.material.bottomsheet.BottomSheetDialog;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w393dp-h851dp-xxhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SheetScreenshotTest {
 private MainActivity last;
 private MainActivity activity(){MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().visible().get();za.co.bacy.ui.CustomerHome.Model m=new za.co.bacy.ui.CustomerHome.Model();m.name="Sample account";m.device="Loop handset";m.reference="QA-ACCOUNT";m.monthlyPayment="R300";m.status="Account connected";m.due="Verified due date";m.remaining="20";m.paidTotal="R300";m.approvedPayments=1;a.setContentView(za.co.bacy.ui.CustomerHome.create(a,m,i->{}));last=a;return a;}
 private void draw(BottomSheetDialog d,String name)throws Exception {View decor=d.getWindow().getDecorView();decor.measure(View.MeasureSpec.makeMeasureSpec(1179,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(2553,View.MeasureSpec.EXACTLY));decor.layout(0,0,1179,2553);Bitmap image=Bitmap.createBitmap(1179,2553,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);View account=last.getWindow().getDecorView();account.measure(View.MeasureSpec.makeMeasureSpec(1179,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(2553,View.MeasureSpec.EXACTLY));account.layout(0,0,1179,2553);account.draw(canvas);canvas.drawColor(0x52000000);decor.draw(canvas);File p=new File("/workspace/loop-phone-manager/artifacts/"+name);try(FileOutputStream out=new FileOutputStream(p)){image.compress(Bitmap.CompressFormat.PNG,100,out);}org.junit.Assert.assertTrue(p.length()>15000);d.dismiss();}
 @Test public void paymentSheet()throws Exception{draw(AccountSheets.payments(activity(),"R300",()->{},()->{},()->{},()->{},()->{}),"payment-sheet-colourful.png");}
 @Test public void accountSheet()throws Exception{draw(AccountSheets.account(activity(),"R300","18 Dec 2026","19 Dec 2026","QA-ACCOUNT",()->{},()->{}),"account-sheet-colourful.png");}
}
